def transform(grid):
    """Replace each nonzero cell by a 3x3 tile marking the zero cells of the source grid."""
    h, w = len(grid), len(grid[0])
    mask = [[cell == 0 for cell in row] for row in grid]
    out = [[0 for _ in range(3 * w)] for _ in range(3 * h)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                for dr in range(h):
                    for dc in range(w):
                        if mask[dr][dc]:
                            out[3*r + dr][3*c + dc] = value
    return out

